import { GoogleGenAI } from "@google/genai";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || ''; // Ensure key is present in environment
const ai = new GoogleGenAI({ apiKey });

export const getTheologicalInsight = async (query: string, context: 'biblical' | 'confessional' | 'general' = 'general'): Promise<string> => {
  if (!apiKey) {
    return "Chave de API não configurada. Por favor, configure a variável de ambiente API_KEY.";
  }

  try {
    const systemPrompt = `
      Você é um assistente teológico especializado na Fé Reformada Clássica.
      Suas respostas devem ser baseadas nas Escrituras Sagradas como norma suprema,
      e subsidiadas pelas Três Formas de Unidade (Confissão Belga, Catecismo de Heidelberg, Cânones de Dort)
      e pelos Padrões de Westminster.

      Mantenha um tom pastoral, acadêmico, porém acessível.
      Responda em Português do Brasil.
      Seja conciso e use formatação Markdown.
    `;

    const modelId = "gemini-2.5-flash"; // Using Flash for speed in interactive UI

    const response = await ai.models.generateContent({
      model: modelId,
      contents: [
        { role: 'user', parts: [{ text: query }] }
      ],
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7, // Balanced creativity and precision
      }
    });

    return response.text || "Não foi possível gerar uma resposta no momento.";
  } catch (error) {
    console.error("Erro ao consultar Gemini:", error);
    return "Ocorreu um erro ao conectar com o assistente teológico.";
  }
};

import React from 'react';
import { BookOpen, Scroll, GraduationCap, Library, Home } from 'lucide-react';
import { Tab } from '../types';

interface NavigationProps {
  currentTab: Tab;
  onTabChange: (tab: Tab) => void;
}

const Navigation: React.FC<NavigationProps> = ({ currentTab, onTabChange }) => {
  const navItems = [
    { id: Tab.HOME, label: 'Início', icon: Home },
    { id: Tab.BIBLE, label: 'Bíblia', icon: BookOpen },
    { id: Tab.CONFESSIONS, label: 'Confissões', icon: Scroll },
    { id: Tab.STUDY, label: 'Estudo', icon: GraduationCap },
    { id: Tab.LIBRARY, label: 'Biblioteca', icon: Library },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-white dark:bg-navy-900 border-t border-gray-200 dark:border-gray-800 pb-safe pt-2 px-6 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-50">
      <div className="flex justify-between items-center max-w-lg mx-auto pb-4">
        {navItems.map((item) => {
          const Icon = item.icon;
          const isActive = currentTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onTabChange(item.id)}
              className={`flex flex-col items-center gap-1 transition-all duration-300 ${
                isActive 
                  ? 'text-petrol-700 dark:text-petrol-100 transform -translate-y-1' 
                  : 'text-gray-400 dark:text-gray-500 hover:text-petrol-500'
              }`}
            >
              <Icon size={22} strokeWidth={isActive ? 2.5 : 1.5} />
              <span className={`text-[10px] font-medium ${isActive ? 'opacity-100' : 'opacity-70'}`}>
                {item.label}
              </span>
            </button>
          );
        })}
      </div>
    </nav>
  );
};

export default Navigation;

import React, { useState } from 'react';
import { Search, ChevronLeft, ChevronRight, MessageSquarePlus, Settings, Book } from 'lucide-react';
import { MOCK_VERSES } from '../constants';
import { getTheologicalInsight } from '../services/geminiService';

const BibleReader: React.FC = () => {
  const [chapter, setChapter] = useState(8);
  const [book, setBook] = useState("Romanos");
  const [fontSize, setFontSize] = useState(18);
  const [isParallel, setIsParallel] = useState(false);
  const [selectedVerse, setSelectedVerse] = useState<string | null>(null);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Filter verses for the current view (mock logic)
  const verses = MOCK_VERSES.filter(v => v.book === book && v.chapter === chapter);
  // Add some mock context verses if array is empty (fallback for demo)
  const displayVerses = verses.length > 0 ? verses : MOCK_VERSES;

  const handleVerseClick = (text: string) => {
    setSelectedVerse(selectedVerse === text ? null : text);
    setAiInsight(null); // Reset insight when changing selection
  };

  const requestInsight = async () => {
    if (!selectedVerse) return;
    setLoadingAi(true);
    const insight = await getTheologicalInsight(
      `Explique teologicamente o versículo: "${selectedVerse}" à luz da teologia reformada. Seja breve.`,
      'biblical'
    );
    setAiInsight(insight);
    setLoadingAi(false);
  };

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900">
      {/* Top Bar Controls */}
      <div className="sticky top-0 bg-white/95 dark:bg-navy-900/95 backdrop-blur-sm border-b border-gray-200 dark:border-gray-800 px-4 py-3 flex items-center justify-between z-10">
         <div className="flex items-center gap-2">
            <button className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full">
               <ChevronLeft size={20} className="text-gray-600 dark:text-gray-300" />
            </button>
            <div className="flex flex-col items-center cursor-pointer">
              <span className="font-serif font-bold text-gray-900 dark:text-white">{book} {chapter}</span>
              <span className="text-[10px] text-gray-500 uppercase tracking-wide">ARA {isParallel && '& ESV'}</span>
            </div>
            <button className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full">
               <ChevronRight size={20} className="text-gray-600 dark:text-gray-300" />
            </button>
         </div>
         <div className="flex items-center gap-3">
            <button onClick={() => setIsParallel(!isParallel)} className={`p-2 rounded-full ${isParallel ? 'bg-petrol-100 text-petrol-700' : 'text-gray-500'}`}>
              <Book size={18} />
            </button>
            <button className="text-gray-500 dark:text-gray-400">
              <Search size={20} />
            </button>
            <button className="text-gray-500 dark:text-gray-400">
              <Settings size={20} />
            </button>
         </div>
      </div>

      {/* Reader Area */}
      <div className="flex-1 overflow-y-auto p-5 pb-32">
        <div className="max-w-2xl mx-auto space-y-6">
          <div className="text-center mb-8">
             <h1 className="font-serif text-3xl font-bold text-gray-900 dark:text-white mb-2">{book}</h1>
             <span className="text-4xl font-serif text-gray-200 dark:text-gray-700">{chapter}</span>
          </div>

          <div className="space-y-4">
            {displayVerses.map((verse, idx) => (
              <div 
                key={idx} 
                className={`group relative rounded-lg transition-colors duration-200 ${selectedVerse === verse.text ? 'bg-gold-500/10 -mx-2 px-2 py-1' : ''}`}
              >
                <span className="text-xs text-gray-400 font-bold mr-2 align-top mt-1 inline-block select-none w-4">{verse.verse}</span>
                <p 
                  onClick={() => handleVerseClick(verse.text)}
                  className={`reading-text inline text-gray-800 dark:text-gray-200 leading-loose cursor-pointer`}
                  style={{ fontSize: `${fontSize}px` }}
                >
                  {verse.text}
                </p>
                {/* Verse Action Menu (Desktop/Hover) */}
                {selectedVerse === verse.text && (
                  <div className="mt-3 flex gap-2 animate-fade-in">
                    <button 
                      onClick={requestInsight}
                      className="flex items-center gap-2 px-3 py-1.5 bg-petrol-600 text-white text-xs font-medium rounded-full shadow hover:bg-petrol-700 transition"
                    >
                      <MessageSquarePlus size={14} />
                      {loadingAi ? 'Analisando...' : 'Insight Teológico'}
                    </button>
                  </div>
                )}

                {/* AI Insight Result */}
                {selectedVerse === verse.text && aiInsight && (
                   <div className="mt-3 p-4 bg-petrol-50 dark:bg-gray-800 border-l-4 border-petrol-500 rounded-r-md text-sm text-gray-800 dark:text-gray-200 leading-relaxed shadow-inner">
                      <h4 className="font-bold text-petrol-700 dark:text-petrol-300 mb-1 flex items-center gap-2">
                        <span className="text-lg">⚓</span> Comentário Reformado
                      </h4>
                      <div dangerouslySetInnerHTML={{ __html: aiInsight.replace(/\n/g, '<br/>') }} />
                   </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default BibleReader;

