import React, { useState, useEffect } from 'react';
import { Tab, ThemeMode } from './types';
import Navigation from './components/Navigation';
import HomeDashboard from './components/HomeDashboard';
import BibleReader from './components/BibleReader';
import ConfessionsReader from './components/ConfessionsReader';
import StudyDashboard from './components/StudyDashboard';
import Library from './components/Library';
import { Moon, Sun } from 'lucide-react';

const App: React.FC = () => {
  const [currentTab, setCurrentTab] = useState<Tab>(Tab.HOME);
  const [theme, setTheme] = useState<ThemeMode>(ThemeMode.LIGHT);

  useEffect(() => {
    // Check system preference or saved preference
    const savedTheme = localStorage.getItem('theme') as ThemeMode;
    if (savedTheme) {
      setTheme(savedTheme);
    } else if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setTheme(ThemeMode.DARK);
    }
  }, []);

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === ThemeMode.DARK) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === ThemeMode.LIGHT ? ThemeMode.DARK : ThemeMode.LIGHT);
  };

  const renderContent = () => {
    switch (currentTab) {
      case Tab.HOME:
        return <HomeDashboard onChangeTab={setCurrentTab} userParams={{ name: 'Peregrino' }} />;
      case Tab.BIBLE:
        return <BibleReader />;
      case Tab.CONFESSIONS:
        return <ConfessionsReader />;
      case Tab.STUDY:
        return <StudyDashboard />;
      case Tab.LIBRARY:
        return <Library />;
      default:
        return <HomeDashboard onChangeTab={setCurrentTab} userParams={{ name: 'Peregrino' }} />;
    }
  };

  return (
    <div className="min-h-screen bg-paper-50 dark:bg-navy-900 flex flex-col max-w-lg mx-auto shadow-2xl overflow-hidden relative border-x border-gray-200 dark:border-gray-800">

      {/* Universal Header for Home */}
      {currentTab === Tab.HOME && (
         <header className="px-6 py-4 flex justify-between items-center bg-white/50 dark:bg-navy-900/50 backdrop-blur-md sticky top-0 z-20">
           <div className="flex flex-col">
             <span className="font-serif text-petrol-700 dark:text-petrol-400 font-bold text-lg tracking-tight">Sola Scriptura</span>
             <span className="text-[10px] uppercase tracking-[0.2em] text-gold-600 font-medium">Confessio</span>
           </div>
           <button 
             onClick={toggleTheme}
             className="p-2 rounded-full bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 transition"
           >
             {theme === ThemeMode.LIGHT ? <Moon size={18} /> : <Sun size={18} />}
           </button>
         </header>
      )}

      {/* Main Content Area */}
      <main className="flex-1 overflow-x-hidden relative h-full">
        {currentTab === Tab.HOME ? (
          <div className="px-6 h-full overflow-y-auto">
            {renderContent()}
          </div>
        ) : (
          <div className="h-full">
            {renderContent()}
          </div>
        )}
      </main>

      {/* Bottom Navigation */}
      <Navigation currentTab={currentTab} onTabChange={setCurrentTab} />

    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useMemo } from 'react';
import { Search, Filter, Bookmark, Share2, X, Check, Tag } from 'lucide-react';
import { MOCK_CONFESSIONS } from '../constants';

const ConfessionsReader: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedSources, setSelectedSources] = useState<string[]>([]);
  const [selectedTags, setSelectedTags] = useState<string[]>([]);

  // Extract unique sources and tags
  const allSources = useMemo(() => Array.from(new Set(MOCK_CONFESSIONS.map(c => c.source))), []);
  const allTags = useMemo(() => Array.from(new Set(MOCK_CONFESSIONS.flatMap(c => c.tags))), []);

  const toggleSource = (source: string) => {
    setSelectedSources(prev =>
      prev.includes(source) ? prev.filter(s => s !== source) : [...prev, source]
    );
  };

  const toggleTag = (tag: string) => {
    setSelectedTags(prev =>
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const activeFiltersCount = selectedSources.length + selectedTags.length;

  const filteredConfessions = MOCK_CONFESSIONS.filter(c => {
    const matchesSearch = searchTerm === '' ||
      c.question?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.answer.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.source.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.reference.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesSource = selectedSources.length === 0 || selectedSources.includes(c.source);
    const matchesTags = selectedTags.length === 0 || c.tags.some(tag => selectedTags.includes(tag));

    return matchesSearch && matchesSource && matchesTags;
  });

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 pb-24">
      {/* Header */}
      <div className="bg-white dark:bg-navy-900 border-b border-gray-200 dark:border-gray-800 p-4 sticky top-0 z-20 shadow-sm">
        <div className="flex justify-between items-center mb-4">
           <h1 className="font-serif text-xl font-bold text-petrol-900 dark:text-white">Símbolos de Fé</h1>
           {(selectedSources.length > 0 || selectedTags.length > 0) && (
             <button 
               onClick={() => { setSelectedSources([]); setSelectedTags([]); setSearchTerm(''); }}
               className="text-xs font-medium text-petrol-600 dark:text-petrol-400 hover:underline"
             >
               Limpar Filtros
             </button>
           )}
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={16} />
            <input 
              type="text"
              placeholder="Buscar em perguntas e respostas..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-gray-100 dark:bg-navy-800 border-none rounded-lg py-2.5 pl-10 pr-4 text-sm focus:ring-2 focus:ring-petrol-500 dark:text-white transition-all"
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`p-2.5 rounded-lg transition-colors relative ${
              showFilters || activeFiltersCount > 0
                ? 'bg-petrol-100 dark:bg-petrol-900 text-petrol-700 dark:text-petrol-300' 
                : 'bg-gray-100 dark:bg-navy-800 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-navy-700'
            }`}
          >
            <Filter size={18} />
            {activeFiltersCount > 0 && !showFilters && (
              <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full"></span>
            )}
          </button>
        </div>

        {/* Filter Panel */}
        {showFilters && (
          <div className="mt-4 pt-4 border-t border-gray-100 dark:border-gray-800 animate-fade-in">
            <div className="space-y-4">
              {/* Sources */}
              <div>
                <h3 className="text-xs font-bold uppercase tracking-wider text-gray-500 dark:text-gray-400 mb-2">Fontes</h3>
                <div className="flex flex-wrap gap-2">
                  {allSources.map(source => {
                    const isSelected = selectedSources.includes(source);
                    return (
                      <button
                        key={source}
                        onClick={() => toggleSource(source)}
                        className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all ${
                          isSelected 
                            ? 'bg-petrol-600 border-petrol-600 text-white shadow-sm' 
                            : 'bg-white dark:bg-navy-800 border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-300 hover:border-petrol-300'
                        }`}
                      >
                        {source}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Tags */}
              <div>
                <h3 className="text-xs font-bold uppercase tracking-wider text-gray-500 dark:text-gray-400 mb-2 flex items-center gap-1">
                  <Tag size={12} /> Temas
                </h3>
                <div className="flex flex-wrap gap-2">
                  {allTags.map(tag => {
                    const isSelected = selectedTags.includes(tag);
                    return (
                      <button
                        key={tag}
                        onClick={() => toggleTag(tag)}
                        className={`px-3 py-1 rounded-md text-xs font-medium transition-all flex items-center gap-1 ${
                          isSelected 
                            ? 'bg-gold-500 text-white shadow-sm' 
                            : 'bg-paper-100 dark:bg-navy-700 text-gray-600 dark:text-gray-300 hover:bg-paper-200'
                        }`}
                      >
                        {isSelected && <Check size={10} />}
                        {tag}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>

            <div className="mt-4 flex justify-center">
               <button 
                  onClick={() => setShowFilters(false)}
                  className="text-gray-400 hover:text-gray-600 dark:text-gray-500 dark:hover:text-gray-300 p-1"
               >
                 <X size={20} />
               </button>
            </div>
          </div>
        )}
      </div>

      {/* List */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {filteredConfessions.length === 0 ? (
          <div className="text-center py-12 text-gray-500 dark:text-gray-400">
             <p className="mb-2">Nenhum resultado encontrado.</p>
             <button 
                onClick={() => { setSelectedSources([]); setSelectedTags([]); setSearchTerm(''); }}
                className="text-petrol-600 dark:text-petrol-400 font-bold text-sm hover:underline"
             >
               Limpar filtros
             </button>
          </div>
        ) : (
          filteredConfessions.map((item) => {
            const isExpanded = expandedId === item.id;
            return (
              <div 
                key={item.id} 
                className={`bg-white dark:bg-navy-800 rounded-xl border transition-all duration-300 overflow-hidden ${isExpanded ? 'border-petrol-500 shadow-md ring-1 ring-petrol-500/20' : 'border-gray-100 dark:border-gray-700 hover:border-petrol-200'}`}
              >
                <div 
                  className="p-4 cursor-pointer"
                  onClick={() => setExpandedId(isExpanded ? null : item.id)}
                >
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[10px] font-bold uppercase tracking-wider text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-navy-900 px-1.5 py-0.5 rounded">
                      {item.source} • {item.reference}
                    </span>
                    {item.tags.length > 0 && (
                       <span className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-petrol-50 dark:bg-petrol-900/30 text-petrol-700 dark:text-petrol-300 border border-petrol-100 dark:border-petrol-800">
                         {item.tags[0]}
                       </span>
                    )}
                  </div>
                  <h3 className="font-serif font-bold text-gray-900 dark:text-gray-100 text-lg leading-tight">
                    {item.question}
                  </h3>

                  {/* Preview of answer if not expanded */}
                  {!isExpanded && (
                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-2 line-clamp-1 opacity-80 font-serif">
                       {item.answer}
                    </p>
                  )}
                </div>

                {isExpanded && (
                  <div className="px-4 pb-4 animate-fade-in">
                    <div className="w-full h-px bg-gray-100 dark:bg-gray-700 mb-4"></div>
                    <p className="font-serif text-gray-800 dark:text-gray-200 leading-loose text-base text-justify">
                      <span className="font-bold text-petrol-600 dark:text-petrol-400 mr-2 text-lg">R.</span>
                      {item.answer}
                    </p>

                    {/* Tags List */}
                    <div className="mt-4 flex flex-wrap gap-2">
                      {item.tags.map(tag => (
                        <span key={tag} className="text-[10px] px-2 py-1 bg-gray-100 dark:bg-navy-700 text-gray-600 dark:text-gray-300 rounded-full">
                          #{tag}
                        </span>
                      ))}
                    </div>

                    {/* Actions */}
                    <div className="flex justify-end gap-3 mt-4 pt-3 border-t border-gray-50 dark:border-gray-700/50">
                      <button className="flex items-center gap-1.5 text-xs font-bold text-gray-500 hover:text-petrol-600 transition-colors">
                        <Bookmark size={14} /> Salvar
                      </button>
                      <button className="flex items-center gap-1.5 text-xs font-bold text-gray-500 hover:text-petrol-600 transition-colors">
                        <Share2 size={14} /> Compartilhar
                      </button>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default ConfessionsReader;

export enum Tab {
  HOME = 'home',
  BIBLE = 'bible',
  CONFESSIONS = 'confessions',
  STUDY = 'study',
  LIBRARY = 'library'
}

export type BibleVersion = 'ARA' | 'NVT' | 'KJV' | 'NA28' | 'BHS';

export interface Verse {
  book: string;
  chapter: number;
  verse: number;
  text: string;
  version: BibleVersion; // Added version identifier
  highlighted?: boolean;
}

export interface ConfessionItem {
  id: string;
  source: string; // e.g., "Catecismo de Heidelberg"
  reference: string; // e.g., "Pergunta 1"
  question?: string;
  answer: string;
  tags: string[];
}

export interface StudyPlan {
  id: string;
  title: string;
  description: string;
  progress: number; // 0 to 100
  totalSessions: number;
  completedSessions: number;
  coverColor: string;
}

export interface InsightRequest {
  passage: string;
  context: string; // "theological", "historical", "devotional"
}

export enum ThemeMode {
  LIGHT = 'light',
  DARK = 'dark'
}

