import React, { useState } from 'react';
import { Search, ChevronLeft, ChevronRight, MessageSquarePlus, Settings, Book, Heart, Languages, Check } from 'lucide-react';
import { MOCK_VERSES } from '../constants';
import { getTheologicalInsight } from '../services/geminiService';
import { BibleVersion } from '../types';

const BibleReader: React.FC = () => {
  const [chapter, setChapter] = useState(8);
  const [book, setBook] = useState("Romanos");
  const [fontSize, setFontSize] = useState(18);
  const [isParallel, setIsParallel] = useState(false);
  const [selectedVerse, setSelectedVerse] = useState<string | null>(null); // Stores verse key "book-chap-verse"
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // New State for Versions and Favorites
  const [primaryVersion, setPrimaryVersion] = useState<BibleVersion>('ARA');
  const [secondaryVersion, setSecondaryVersion] = useState<BibleVersion>('NA28');
  const [favorites, setFavorites] = useState<string[]>([]); // Array of "book-chap-verse"
  const [showVersionSelector, setShowVersionSelector] = useState<'primary' | 'secondary' | null>(null);

  // Helper to generate a unique key for a verse (independent of version)
  const getVerseKey = (v: { book: string, chapter: number, verse: number }) => `${v.book}-${v.chapter}-${v.verse}`;

  // Filter verses logic
  const getVersesForVersion = (ver: BibleVersion) => {
    return MOCK_VERSES.filter(v => v.book === book && v.chapter === chapter && v.version === ver);
  };

  const primaryVerses = getVersesForVersion(primaryVersion);
  const secondaryVerses = getVersesForVersion(secondaryVersion);

  // Use primary verses to drive the list rendering
  const displayVerses = primaryVerses.length > 0 ? primaryVerses : getVersesForVersion('ARA');

  const handleVerseClick = (vKey: string) => {
    setSelectedVerse(selectedVerse === vKey ? null : vKey);
    setAiInsight(null);
  };

  const toggleFavorite = (vKey: string) => {
    setFavorites(prev => 
      prev.includes(vKey) ? prev.filter(k => k !== vKey) : [...prev, vKey]
    );
  };

  const requestInsight = async (text: string) => {
    setLoadingAi(true);
    const insight = await getTheologicalInsight(
      `Explique teologicamente o versículo: "${text}" à luz da teologia reformada. Se houver termos no original (Grego/Hebraico) relevantes, mencione. Seja breve.`,
      'biblical'
    );
    setAiInsight(insight);
    setLoadingAi(false);
  };

  // UI Helpers
  const isRTL = (ver: BibleVersion) => ver === 'BHS';
  const getFontClass = (ver: BibleVersion) => {
    if (ver === 'BHS') return 'font-serif text-xl leading-loose text-right';
    if (ver === 'NA28') return 'font-serif text-lg leading-relaxed';
    return 'reading-text leading-loose';
  };

  const availableVersions: { code: BibleVersion, label: string }[] = [
    { code: 'ARA', label: 'Almeida Revista e Atualizada' },
    { code: 'NVT', label: 'Nova Versão Transformadora' },
    { code: 'KJV', label: 'King James Version' },
    { code: 'NA28', label: 'Nestle-Aland 28 (Grego)' },
    { code: 'BHS', label: 'Biblia Hebraica (Hebraico)' },
  ];

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 relative">

      {/* Version Selector Modal/Dropdown Overlay */}
      {showVersionSelector && (
        <div className="absolute inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-start justify-center pt-20 animate-fade-in" onClick={() => setShowVersionSelector(null)}>
          <div className="bg-white dark:bg-navy-800 rounded-xl shadow-2xl w-64 overflow-hidden border border-gray-200 dark:border-gray-700" onClick={e => e.stopPropagation()}>
            <div className="p-3 bg-petrol-50 dark:bg-navy-900 border-b border-gray-100 dark:border-gray-700">
              <h3 className="text-xs font-bold uppercase tracking-wider text-gray-500">
                Selecione a Versão {showVersionSelector === 'secondary' ? 'Secundária' : 'Principal'}
              </h3>
            </div>
            {availableVersions.map(v => (
              <button
                key={v.code}
                onClick={() => {
                  if (showVersionSelector === 'primary') setPrimaryVersion(v.code);
                  else setSecondaryVersion(v.code);
                  setShowVersionSelector(null);
                }}
                className="w-full text-left px-4 py-3 text-sm hover:bg-gray-50 dark:hover:bg-navy-700 flex items-center justify-between text-gray-800 dark:text-gray-200"
              >
                <span><span className="font-bold">{v.code}</span> - {v.label}</span>
                {(showVersionSelector === 'primary' ? primaryVersion : secondaryVersion) === v.code && <Check size={16} className="text-petrol-600" />}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Top Bar Controls */}
      <div className="sticky top-0 bg-white/95 dark:bg-navy-900/95 backdrop-blur-sm border-b border-gray-200 dark:border-gray-800 px-4 py-3 flex items-center justify-between z-10">
         <div className="flex items-center gap-2">
            <button className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full">
               <ChevronLeft size={20} className="text-gray-600 dark:text-gray-300" />
            </button>
            <div className="flex flex-col items-center cursor-pointer group">
              <span className="font-serif font-bold text-gray-900 dark:text-white">{book} {chapter}</span>
              <div className="flex items-center gap-1 text-[10px] text-gray-500 uppercase tracking-wide">
                <span 
                  onClick={() => setShowVersionSelector('primary')}
                  className="hover:text-petrol-600 hover:underline cursor-pointer"
                >
                  {primaryVersion}
                </span>
                {isParallel && (
                  <>
                    <span>&</span>
                    <span 
                      onClick={() => setShowVersionSelector('secondary')}
                      className="hover:text-petrol-600 hover:underline cursor-pointer"
                    >
                      {secondaryVersion}
                    </span>
                  </>
                )}
              </div>
            </div>
            <button className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full">
               <ChevronRight size={20} className="text-gray-600 dark:text-gray-300" />
            </button>
         </div>
         <div className="flex items-center gap-2">
            <button 
              onClick={() => setIsParallel(!isParallel)} 
              className={`p-2 rounded-full transition-colors ${isParallel ? 'bg-petrol-100 text-petrol-700 dark:bg-petrol-900 dark:text-petrol-100' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}
              title="Modo Paralelo"
            >
              <Book size={18} />
            </button>
            <button className="text-gray-500 dark:text-gray-400 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full">
              <Settings size={20} />
            </button>
         </div>
      </div>

      {/* Reader Area */}
      <div className="flex-1 overflow-y-auto p-4 pb-32">
        <div className={`max-w-4xl mx-auto space-y-6 ${isParallel ? 'w-full' : 'max-w-2xl'}`}>
          <div className="text-center mb-8">
             <h1 className="font-serif text-3xl font-bold text-gray-900 dark:text-white mb-2">{book}</h1>
             <span className="text-4xl font-serif text-gray-200 dark:text-gray-700">{chapter}</span>
          </div>

          <div className="space-y-6">
            {displayVerses.map((verse, idx) => {
              const vKey = getVerseKey(verse);
              const isSelected = selectedVerse === vKey;
              const isFav = favorites.includes(vKey);
              const secondaryVerseText = secondaryVerses.find(v => v.verse === verse.verse)?.text;

              return (
                <div 
                  key={vKey} 
                  className={`relative rounded-xl transition-all duration-300 
                    ${isSelected ? 'bg-white dark:bg-navy-800 shadow-lg ring-1 ring-petrol-500/20 -mx-3 px-3 py-4' : 'hover:bg-white/50 dark:hover:bg-white/5'}`}
                >
                  <div className={`grid ${isParallel ? 'grid-cols-2 gap-6' : 'grid-cols-1'}`}>

                    {/* Primary Version Column */}
                    <div className="relative">
                       <span className={`text-[10px] font-bold absolute -left-0 top-1.5 w-4 text-gray-400 select-none ${isFav ? 'text-gold-500' : ''}`}>
                         {verse.verse}
                       </span>
                       <div className="pl-6">
                          <p 
                            onClick={() => handleVerseClick(vKey)}
                            className={`${getFontClass(primaryVersion)} text-gray-800 dark:text-gray-200 cursor-pointer`}
                            style={{ fontSize: `${fontSize}px`, direction: isRTL(primaryVersion) ? 'rtl' : 'ltr' }}
                          >
                            {verse.text}
                          </p>
                       </div>
                    </div>

                    {/* Secondary Version Column (Parallel Mode) */}
                    {isParallel && (
                       <div className="pl-2 border-l border-gray-100 dark:border-gray-800">
                          {secondaryVerseText ? (
                            <p 
                              onClick={() => handleVerseClick(vKey)}
                              className={`${getFontClass(secondaryVersion)} text-gray-600 dark:text-gray-400 cursor-pointer`}
                              style={{ fontSize: `${fontSize}px`, direction: isRTL(secondaryVersion) ? 'rtl' : 'ltr' }}
                            >
                              {secondaryVerseText}
                            </p>
                          ) : (
                            <span className="text-xs text-gray-300 italic">Texto indisponível nesta versão.</span>
                          )}
                       </div>
                    )}
                  </div>

                  {/* Action Menu (Visible on Select) */}
                  {isSelected && (
                    <div className="mt-4 flex gap-3 animate-fade-in pl-6 border-t border-gray-100 dark:border-gray-700 pt-3">
                      <button 
                        onClick={() => toggleFavorite(vKey)}
                        className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-full border transition-colors
                          ${isFav 
                            ? 'bg-gold-50 border-gold-200 text-gold-600 dark:bg-gold-900/20 dark:border-gold-700' 
                            : 'bg-white border-gray-200 text-gray-600 hover:border-petrol-300 dark:bg-navy-700 dark:border-gray-600 dark:text-gray-300'}`}
                      >
                        <Heart size={14} fill={isFav ? "currentColor" : "none"} />
                        {isFav ? 'Salvo' : 'Salvar'}
                      </button>

                      <button 
                        onClick={() => requestInsight(verse.text)}
                        className="flex items-center gap-2 px-3 py-1.5 bg-petrol-600 text-white text-xs font-bold rounded-full shadow hover:bg-petrol-700 transition"
                      >
                        <MessageSquarePlus size={14} />
                        {loadingAi ? 'Analisando...' : 'Insight Teológico'}
                      </button>
                    </div>
                  )}

                  {/* AI Insight Result */}
                  {isSelected && aiInsight && (
                     <div className="mt-4 mx-6 p-4 bg-petrol-50 dark:bg-navy-900/50 border border-petrol-100 dark:border-petrol-900 rounded-lg text-sm text-gray-800 dark:text-gray-200 leading-relaxed animate-fade-in">
                        <h4 className="font-bold text-petrol-700 dark:text-petrol-300 mb-2 flex items-center gap-2 text-xs uppercase tracking-wider">
                           <MessageSquarePlus size={14} /> Comentário Reformado
                        </h4>
                        <div dangerouslySetInnerHTML={{ __html: aiInsight.replace(/\n/g, '<br/>') }} />
                     </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

export default BibleReader;

