import React, { useState, useEffect } from 'react';
import { BookMarked, History, Highlighter, Plus, Calendar, Target, Trash2, X, ChevronRight } from 'lucide-react';
import { BibleReadingPlan } from '../types';

const Library: React.FC = () => {
  const [plans, setPlans] = useState<BibleReadingPlan[]>([]);
  const [showModal, setShowModal] = useState(false);

  // Form State
  const [newPlanName, setNewPlanName] = useState('');
  const [targetDate, setTargetDate] = useState('');
  const [scope, setScope] = useState<'full' | 'nt' | 'ot'>('full');

  // Constants
  const CHAPTERS_FULL = 1189;
  const CHAPTERS_OT = 929;
  const CHAPTERS_NT = 260;

  const categories = [
    { title: 'Anotações', icon: BookMarked, count: 12 },
    { title: 'Destaques', icon: Highlighter, count: 45 },
    { title: 'Histórico', icon: History, count: null },
  ];

  const getChaptersCount = () => {
    if (scope === 'nt') return CHAPTERS_NT;
    if (scope === 'ot') return CHAPTERS_OT;
    return CHAPTERS_FULL;
  };

  const calculateDailyGoal = (end: string, totalChapters: number) => {
    if (!end) return 0;
    const start = new Date();
    const endDate = new Date(end);
    const diffTime = Math.abs(endDate.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 

    if (diffDays <= 0) return totalChapters; // Late or today
    return Math.ceil(totalChapters / diffDays);
  };

  const handleCreatePlan = () => {
    if (!newPlanName || !targetDate) return;

    const total = getChaptersCount();
    const daily = calculateDailyGoal(targetDate, total);

    const newPlan: BibleReadingPlan = {
      id: Date.now().toString(),
      title: newPlanName,
      startDate: new Date().toISOString(),
      endDate: targetDate,
      totalChapters: total,
      chaptersRead: 0,
      dailyGoal: daily
    };

    setPlans([...plans, newPlan]);
    setShowModal(false);
    // Reset form
    setNewPlanName('');
    setTargetDate('');
    setScope('full');
  };

  const handleDeletePlan = (id: string) => {
    setPlans(plans.filter(p => p.id !== id));
  };

  // Mock initial data if empty
  useEffect(() => {
    if (plans.length === 0) {
      // Optional: Load from local storage or set empty
    }
  }, []);

  const projectedDailyGoal = calculateDailyGoal(targetDate, getChaptersCount());

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 p-6 pb-24 overflow-y-auto relative">
      <h1 className="font-serif text-2xl font-bold text-petrol-900 dark:text-white mb-6">Minha Biblioteca</h1>

      {/* Top Categories */}
      <div className="grid grid-cols-2 gap-4 mb-8">
        {categories.map((cat, idx) => (
          <div key={idx} className="bg-white dark:bg-navy-800 p-4 rounded-xl border border-gray-100 dark:border-gray-700 flex flex-col items-center justify-center gap-2 aspect-[4/3] hover:bg-gray-50 dark:hover:bg-navy-700 transition cursor-pointer shadow-sm">
            <cat.icon size={24} className="text-petrol-600 dark:text-petrol-400" />
            <span className="font-medium text-gray-900 dark:text-gray-100 text-sm">{cat.title}</span>
            {cat.count !== null && (
              <span className="text-[10px] text-gray-500 bg-gray-100 dark:bg-navy-900 px-2 py-0.5 rounded-full">{cat.count}</span>
            )}
          </div>
        ))}
      </div>

      {/* Reading Plans Section */}
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-sm font-bold uppercase tracking-wider text-gray-500 dark:text-gray-400">
          Meus Planos de Leitura
        </h2>
        <button 
          onClick={() => setShowModal(true)}
          className="flex items-center gap-1 text-xs font-bold text-petrol-700 dark:text-petrol-300 hover:underline"
        >
          <Plus size={14} /> Novo Plano
        </button>
      </div>

      {plans.length === 0 ? (
        <div 
          onClick={() => setShowModal(true)}
          className="bg-white dark:bg-navy-800 rounded-xl p-8 border-2 border-dashed border-gray-200 dark:border-gray-700 flex flex-col items-center justify-center text-center cursor-pointer hover:border-petrol-300 transition-colors group"
        >
          <div className="w-12 h-12 rounded-full bg-petrol-50 dark:bg-navy-700 flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
            <Calendar className="text-petrol-600 dark:text-petrol-400" size={24} />
          </div>
          <h3 className="font-bold text-gray-900 dark:text-white mb-1">Criar Plano de Leitura</h3>
          <p className="text-xs text-gray-500 dark:text-gray-400 max-w-[200px]">
            Defina uma meta e um prazo para ler a Bíblia completa ou partes dela.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {plans.map(plan => {
            const progress = Math.round((plan.chaptersRead / plan.totalChapters) * 100);
            const daysLeft = Math.ceil((new Date(plan.endDate).getTime() - new Date().getTime()) / (1000 * 3600 * 24));

            return (
              <div key={plan.id} className="bg-white dark:bg-navy-800 rounded-xl p-5 border border-gray-100 dark:border-gray-700 shadow-sm relative group">
                <button 
                  onClick={() => handleDeletePlan(plan.id)}
                  className="absolute top-4 right-4 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <Trash2 size={16} />
                </button>

                <h3 className="font-serif font-bold text-lg text-gray-900 dark:text-white mb-1">{plan.title}</h3>
                <div className="flex items-center gap-3 text-xs text-gray-500 dark:text-gray-400 mb-4">
                  <span className="flex items-center gap-1"><Calendar size={12} /> {daysLeft} dias restantes</span>
                  <span className="flex items-center gap-1"><Target size={12} /> {plan.dailyGoal} cap/dia</span>
                </div>

                <div className="flex items-center gap-3">
                  <div className="flex-1 h-2 bg-gray-100 dark:bg-navy-900 rounded-full overflow-hidden">
                    <div className="h-full bg-gold-500 rounded-full" style={{ width: `${progress}%` }}></div>
                  </div>
                  <span className="text-xs font-bold text-gray-700 dark:text-gray-300">{progress}%</span>
                </div>

                <div className="mt-4 pt-3 border-t border-gray-100 dark:border-gray-700 flex justify-between items-center">
                   <span className="text-xs text-gray-400">Leitura de hoje: {plan.dailyGoal} caps</span>
                   <button className="text-petrol-600 dark:text-petrol-400 text-xs font-bold flex items-center gap-1 hover:underline">
                     Registrar Leitura <ChevronRight size={14} />
                   </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Create Plan Modal */}
      {showModal && (
        <div className="absolute inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-4 animate-fade-in">
          <div className="bg-white dark:bg-navy-800 w-full max-w-sm rounded-2xl p-6 shadow-2xl border border-gray-200 dark:border-gray-700">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-serif text-xl font-bold text-gray-900 dark:text-white">Novo Plano</h3>
              <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-1">Nome do Plano</label>
                <input 
                  type="text" 
                  value={newPlanName}
                  onChange={(e) => setNewPlanName(e.target.value)}
                  placeholder="Ex: Bíblia em 1 ano"
                  className="w-full bg-gray-50 dark:bg-navy-900 border border-gray-200 dark:border-gray-700 rounded-lg p-3 text-sm focus:ring-2 focus:ring-petrol-500 outline-none dark:text-white"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-1">Escopo</label>
                <div className="flex gap-2">
                  {[
                    { id: 'full', label: 'Toda a Bíblia' },
                    { id: 'nt', label: 'Novo Testamento' },
                    { id: 'ot', label: 'Antigo Testamento' }
                  ].map((opt) => (
                    <button
                      key={opt.id}
                      onClick={() => setScope(opt.id as any)}
                      className={`flex-1 py-2 text-xs font-medium rounded-lg border ${
                        scope === opt.id 
                          ? 'bg-petrol-50 dark:bg-petrol-900 border-petrol-500 text-petrol-700 dark:text-petrol-300' 
                          : 'border-gray-200 dark:border-gray-700 text-gray-500 dark:text-gray-400'
                      }`}
                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-1">Data de Término</label>
                <input 
                  type="date" 
                  value={targetDate}
                  min={new Date().toISOString().split('T')[0]}
                  onChange={(e) => setTargetDate(e.target.value)}
                  className="w-full bg-gray-50 dark:bg-navy-900 border border-gray-200 dark:border-gray-700 rounded-lg p-3 text-sm focus:ring-2 focus:ring-petrol-500 outline-none dark:text-white"
                />
              </div>

              {targetDate && (
                <div className="bg-gold-50 dark:bg-navy-900/50 p-4 rounded-lg flex items-start gap-3 border border-gold-200 dark:border-gold-900/30">
                  <Target className="text-gold-600 dark:text-gold-500 mt-0.5" size={18} />
                  <div>
                    <p className="text-sm font-bold text-gray-900 dark:text-white">
                      {projectedDailyGoal} capítulos por dia
                    </p>
                    <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                      Para terminar em {new Date(targetDate).toLocaleDateString('pt-BR')}
                    </p>
                  </div>
                </div>
              )}

              <button 
                onClick={handleCreatePlan}
                disabled={!newPlanName || !targetDate}
                className="w-full bg-petrol-600 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-petrol-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all mt-2"
              >
                Criar Plano
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Library;

