import { GoogleGenAI, SchemaType } from "@google/genai";
import { Verse, BibleVersion } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || ''; // Ensure key is present in environment
const ai = new GoogleGenAI({ apiKey });

export const getTheologicalInsight = async (query: string, context: 'biblical' | 'confessional' | 'general' = 'general'): Promise<string> => {
  if (!apiKey) {
    return "Chave de API não configurada. Por favor, configure a variável de ambiente API_KEY.";
  }

  try {
    const systemPrompt = `
      Você é um assistente teológico especializado na Fé Reformada Clássica.
      Suas respostas devem ser baseadas nas Escrituras Sagradas como norma suprema,
      e subsidiadas pelas Três Formas de Unidade (Confissão Belga, Catecismo de Heidelberg, Cânones de Dort)
      e pelos Padrões de Westminster.

      Mantenha um tom pastoral, acadêmico, porém acessível.
      Responda em Português do Brasil.
      Seja conciso e use formatação Markdown.
    `;

    const modelId = "gemini-2.5-flash"; // Using Flash for speed in interactive UI

    const response = await ai.models.generateContent({
      model: modelId,
      contents: [
        { role: 'user', parts: [{ text: query }] }
      ],
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7, // Balanced creativity and precision
      }
    });

    return response.text || "Não foi possível gerar uma resposta no momento.";
  } catch (error) {
    console.error("Erro ao consultar Gemini:", error);
    return "Ocorreu um erro ao conectar com o assistente teológico.";
  }
};

export const getBibleChapter = async (book: string, chapter: number, version: BibleVersion): Promise<Verse[]> => {
  if (!apiKey) return [];

  // Mapeamento de nomes de versões para instruções mais claras ao modelo
  const versionMap: Record<BibleVersion, string> = {
    'ARA': 'Almeida Revista e Atualizada (Português)',
    'NVT': 'Nova Versão Transformadora (Português)',
    'KJV': 'King James Version (Inglês)',
    'NA28': 'Nestle-Aland 28 (Grego Koiné)',
    'BHS': 'Biblia Hebraica Stuttgartensia (Hebraico)'
  };

  const prompt = `
    Forneça o texto completo da Bíblia para o livro de ${book}, capítulo ${chapter}, usando exatamente a versão "${versionMap[version]}".
    Certifique-se de que o texto corresponda fielmente à versão solicitada.
    Se for Grego ou Hebraico, use os caracteres originais.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: SchemaType.ARRAY,
          items: {
            type: SchemaType.OBJECT,
            properties: {
              verse: { type: SchemaType.INTEGER },
              text: { type: SchemaType.STRING }
            },
            required: ["verse", "text"]
          }
        }
      }
    });

    const jsonText = response.text;
    if (!jsonText) return [];

    const parsedData = JSON.parse(jsonText) as { verse: number, text: string }[];

    // Map to Verse interface
    return parsedData.map(item => ({
      book,
      chapter,
      verse: item.verse,
      text: item.text,
      version
    }));

  } catch (error) {
    console.error("Erro ao buscar capítulo da Bíblia:", error);
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { Search, ChevronLeft, ChevronRight, MessageSquarePlus, Settings, Book, Heart, Languages, Check, X, Grid, Loader2 } from 'lucide-react';
import { MOCK_VERSES, BIBLE_BOOKS } from '../constants';
import { getTheologicalInsight, getBibleChapter } from '../services/geminiService';
import { BibleVersion, Verse } from '../types';

const BibleReader: React.FC = () => {
  const [chapter, setChapter] = useState(8);
  const [book, setBook] = useState("Romanos");
  const [fontSize, setFontSize] = useState(18);
  const [isParallel, setIsParallel] = useState(false);
  const [selectedVerse, setSelectedVerse] = useState<string | null>(null); // Stores verse key "book-chap-verse"
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Versions and Favorites
  const [primaryVersion, setPrimaryVersion] = useState<BibleVersion>('ARA');
  const [secondaryVersion, setSecondaryVersion] = useState<BibleVersion>('NA28');
  const [favorites, setFavorites] = useState<string[]>([]); // Array of "book-chap-verse"
  const [showVersionSelector, setShowVersionSelector] = useState<'primary' | 'secondary' | null>(null);

  // Dynamic Content State
  const [primaryContent, setPrimaryContent] = useState<Verse[]>([]);
  const [secondaryContent, setSecondaryContent] = useState<Verse[]>([]);
  const [isLoadingText, setIsLoadingText] = useState(false);

  // Navigation Modal State
  const [showNav, setShowNav] = useState(false);
  const [navTab, setNavTab] = useState<'AT' | 'NT'>('NT');
  const [selectedBookForNav, setSelectedBookForNav] = useState<string | null>(null);

  // Load Content Effect
  useEffect(() => {
    const loadContent = async () => {
      setIsLoadingText(true);

      // 1. Load Primary Version
      const localPrimary = MOCK_VERSES.filter(v => v.book === book && v.chapter === chapter && v.version === primaryVersion);
      if (localPrimary.length > 0) {
        setPrimaryContent(localPrimary);
      } else {
        // Fetch from AI if not local
        const fetched = await getBibleChapter(book, chapter, primaryVersion);
        setPrimaryContent(fetched);
      }

      // 2. Load Secondary Version (if parallel)
      if (isParallel) {
        const localSecondary = MOCK_VERSES.filter(v => v.book === book && v.chapter === chapter && v.version === secondaryVersion);
        if (localSecondary.length > 0) {
          setSecondaryContent(localSecondary);
        } else {
           const fetched = await getBibleChapter(book, chapter, secondaryVersion);
           setSecondaryContent(fetched);
        }
      }

      setIsLoadingText(false);
    };

    loadContent();
  }, [book, chapter, primaryVersion, secondaryVersion, isParallel]);


  // Helper to generate a unique key for a verse (independent of version)
  const getVerseKey = (v: { book: string, chapter: number, verse: number }) => `${v.book}-${v.chapter}-${v.verse}`;

  const handleVerseClick = (vKey: string) => {
    setSelectedVerse(selectedVerse === vKey ? null : vKey);
    setAiInsight(null);
  };

  const toggleFavorite = (vKey: string) => {
    setFavorites(prev => 
      prev.includes(vKey) ? prev.filter(k => k !== vKey) : [...prev, vKey]
    );
  };

  const requestInsight = async (text: string) => {
    setLoadingAi(true);
    const insight = await getTheologicalInsight(
      `Explique teologicamente o versículo: "${text}" à luz da teologia reformada. Se houver termos no original (Grego/Hebraico) relevantes, mencione. Seja breve.`,
      'biblical'
    );
    setAiInsight(insight);
    setLoadingAi(false);
  };

  const handleBookSelect = (bookName: string) => {
    setSelectedBookForNav(bookName);
  };

  const handleChapterSelect = (chap: number) => {
    if (selectedBookForNav) {
      setBook(selectedBookForNav);
      setChapter(chap);
      setShowNav(false);
      setSelectedBookForNav(null); // Reset for next time
    }
  };

  // UI Helpers
  const isRTL = (ver: BibleVersion) => ver === 'BHS';
  const getFontClass = (ver: BibleVersion) => {
    if (ver === 'BHS') return 'font-serif text-xl leading-loose text-right';
    if (ver === 'NA28') return 'font-serif text-lg leading-relaxed';
    return 'reading-text leading-loose';
  };

  const availableVersions: { code: BibleVersion, label: string }[] = [
    { code: 'ARA', label: 'Almeida Revista e Atualizada' },
    { code: 'NVT', label: 'Nova Versão Transformadora' },
    { code: 'KJV', label: 'King James Version' },
    { code: 'NA28', label: 'Nestle-Aland 28 (Grego)' },
    { code: 'BHS', label: 'Biblia Hebraica (Hebraico)' },
  ];

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 relative">

      {/* Navigation Modal */}
      {showNav && (
        <div className="absolute inset-0 z-50 bg-white dark:bg-navy-900 animate-fade-in flex flex-col">
          {/* Nav Header */}
          <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-800 flex items-center justify-between bg-white dark:bg-navy-900 sticky top-0">
             {selectedBookForNav ? (
               <button onClick={() => setSelectedBookForNav(null)} className="flex items-center gap-1 text-gray-500 hover:text-petrol-600">
                 <ChevronLeft size={20} /> <span className="text-sm font-bold">Voltar</span>
               </button>
             ) : (
               <h2 className="text-lg font-serif font-bold text-petrol-900 dark:text-white">Navegar</h2>
             )}
             <button onClick={() => { setShowNav(false); setSelectedBookForNav(null); }} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-navy-800 text-gray-500">
               <X size={24} />
             </button>
          </div>

          {/* Content */}
          <div className="flex-1 overflow-y-auto">
            {!selectedBookForNav ? (
              // Book Selection List
              <div className="p-4">
                {/* Tabs */}
                <div className="flex bg-gray-100 dark:bg-navy-800 p-1 rounded-xl mb-6 sticky top-0 z-10">
                  {(['AT', 'NT'] as const).map(tab => (
                    <button
                      key={tab}
                      onClick={() => setNavTab(tab)}
                      className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${
                        navTab === tab 
                          ? 'bg-white dark:bg-navy-700 text-petrol-700 dark:text-white shadow-sm' 
                          : 'text-gray-500 dark:text-gray-400'
                      }`}
                    >
                      {tab === 'AT' ? 'Antigo Testamento' : 'Novo Testamento'}
                    </button>
                  ))}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  {BIBLE_BOOKS.filter(b => b.test === navTab).map(b => (
                    <button 
                      key={b.name}
                      onClick={() => handleBookSelect(b.name)}
                      className="text-left px-4 py-3 rounded-lg hover:bg-petrol-50 dark:hover:bg-navy-800 border border-transparent hover:border-petrol-100 dark:hover:border-navy-700 transition-colors"
                    >
                      <span className="font-serif font-medium text-gray-800 dark:text-gray-200">{b.name}</span>
                    </button>
                  ))}
                </div>
              </div>
            ) : (
              // Chapter Selection Grid
              <div className="p-6">
                <h3 className="text-center font-serif text-2xl font-bold text-gray-900 dark:text-white mb-8">
                  {selectedBookForNav}
                </h3>
                <div className="grid grid-cols-5 gap-4">
                   {Array.from({ length: BIBLE_BOOKS.find(b => b.name === selectedBookForNav)?.chapters || 0 }, (_, i) => i + 1).map(chapNum => (
                     <button
                       key={chapNum}
                       onClick={() => handleChapterSelect(chapNum)}
                       className={`aspect-square rounded-full flex items-center justify-center font-medium text-lg transition-all
                         ${(book === selectedBookForNav && chapter === chapNum)
                           ? 'bg-petrol-600 text-white shadow-md' 
                           : 'bg-gray-100 dark:bg-navy-800 text-gray-700 dark:text-gray-300 hover:bg-petrol-100 dark:hover:bg-navy-700'
                         }
                       `}
                     >
                       {chapNum}
                     </button>
                   ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Version Selector Modal/Dropdown Overlay */}
      {showVersionSelector && (
        <div className="absolute inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-start justify-center pt-20 animate-fade-in" onClick={() => setShowVersionSelector(null)}>
          <div className="bg-white dark:bg-navy-800 rounded-xl shadow-2xl w-64 overflow-hidden border border-gray-200 dark:border-gray-700" onClick={e => e.stopPropagation()}>
            <div className="p-3 bg-petrol-50 dark:bg-navy-900 border-b border-gray-100 dark:border-gray-700">
              <h3 className="text-xs font-bold uppercase tracking-wider text-gray-500">
