// Initialize Gemini Client
const apiKey = process.env.API_KEY || ''; // Ensure key is present in environment
const ai = new GoogleGenAI({ apiKey });

export const getTheologicalInsight = async (query: string, context: 'biblical' | 'confessional' | 'general' = 'general'): Promise<string> => {
  if (!apiKey) {
    return "Chave de API não configurada. Por favor, configure a variável de ambiente API_KEY.";
  }

  try {
    const systemPrompt = `
      Você é um assistente teológico especializado na Fé Reformada Clássica.
      Suas respostas devem ser baseadas nas Escrituras Sagradas como norma suprema,
      e subsidiadas pelas Três Formas de Unidade (Confissão Belga, Catecismo de Heidelberg, Cânones de Dort)
      e pelos Padrões de Westminster.

      Mantenha um tom pastoral, acadêmico, porém acessível.
      Responda em Português do Brasil.
      Seja conciso e use formatação Markdown.
    `;

    const modelId = "gemini-2.5-flash"; // Using Flash for speed in interactive UI

    const response = await ai.models.generateContent({
      model: modelId,
      contents: [
        { role: 'user', parts: [{ text: query }] }
      ],
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7, // Balanced creativity and precision
      }
    });

    return response.text || "Não foi possível gerar uma resposta no momento.";
  } catch (error) {
    console.error("Erro ao consultar Gemini:", error);
    return "Ocorreu um erro ao conectar com o assistente teológico.";
  }
};

export const getBibleChapter = async (book: string, chapter: number, version: BibleVersion): Promise<Verse[]> => {
  if (!apiKey) return [];

  // Mapeamento de nomes de versões para instruções mais claras ao modelo
  const versionMap: Record<BibleVersion, string> = {
    'ARA': 'Almeida Revista e Atualizada (Português)',
    'NVT': 'Nova Versão Transformadora (Português)',
    'KJV': 'King James Version (Inglês)',
    'NA28': 'Nestle-Aland 28 (Grego Koiné)',
    'BHS': 'Biblia Hebraica Stuttgartensia (Hebraico)'
  };

  const prompt = `
    Forneça o texto completo da Bíblia para o livro de ${book}, capítulo ${chapter}, usando exatamente a versão "${versionMap[version]}".
    Certifique-se de que o texto corresponda fielmente à versão solicitada.
    Se for Grego ou Hebraico, use os caracteres originais.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              verse: { type: Type.INTEGER },
              text: { type: Type.STRING }
            },
            required: ["verse", "text"]
          }
        }
      }
    });

    const jsonText = response.text;
    if (!jsonText) return [];

    const parsedData = JSON.parse(jsonText) as { verse: number, text: string }[];

    // Map to Verse interface
    return parsedData.map(item => ({
      book,
      chapter,
      verse: item.verse,
      text: item.text,
      version
    }));

  } catch (error) {
    console.error("Erro ao buscar capítulo da Bíblia:", error);
    return [];
  }
};

import { Verse } from '../types';

const DB_NAME = 'SolaScripturaDB';
const DB_VERSION = 1;
const STORE_VERSES = 'verses';
const STORE_META = 'metadata';

export interface StoredBibleMeta {
  code: string; // e.g., 'ACF', 'NIV'
  name: string;
  language: string;
  importedAt: number;
}

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = (event) => reject('Erro ao abrir banco de dados');

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;

      // Store for Verses
      if (!db.objectStoreNames.contains(STORE_VERSES)) {
        const verseStore = db.createObjectStore(STORE_VERSES, { keyPath: 'id' }); // id: "VERSION-BOOK-CHAP-VERSE"
        verseStore.createIndex('version', 'version', { unique: false });
        verseStore.createIndex('locator', ['version', 'book', 'chapter'], { unique: false });
      }

      // Store for Bible Metadata (Available versions)
      if (!db.objectStoreNames.contains(STORE_META)) {
        db.createObjectStore(STORE_META, { keyPath: 'code' });
      }
    };

    request.onsuccess = (event) => {
      resolve((event.target as IDBOpenDBRequest).result);
    };
  });
};

export const saveBibleVersion = async (meta: StoredBibleMeta, verses: Verse[]): Promise<void> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_VERSES, STORE_META], 'readwrite');

    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject('Erro na transação de salvamento');

    const metaStore = transaction.objectStore(STORE_META);
    metaStore.put(meta);

    const verseStore = transaction.objectStore(STORE_VERSES);
    verses.forEach(v => {
      // Create a unique compound ID
      const id = `${meta.code}-${v.book}-${v.chapter}-${v.verse}`;
      verseStore.put({ ...v, id, version: meta.code });
    });
  });
};

export const getStoredVersions = async (): Promise<StoredBibleMeta[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_META], 'readonly');
    const store = transaction.objectStore(STORE_META);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const getStoredChapter = async (version: string, book: string, chapter: number): Promise<Verse[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_VERSES], 'readonly');
    const store = transaction.objectStore(STORE_VERSES);
    const index = store.index('locator');
    const request = index.getAll([version, book, chapter]);

    request.onsuccess = () => {
      const results = request.result as Verse[];
      // Sort by verse number to ensure correct order
      resolve(results.sort((a, b) => a.verse - b.verse));
    };
    request.onerror = () => reject(request.error);
  });
};

import JSZip from 'jszip';
import { Verse } from '../types';
import { BIBLE_BOOKS } from '../constants';

// Helper to normalize book names
const normalizeBookName = (input: string): string => {
  const normalizedInput = input.trim().toLowerCase();

  // Simple mapping - In a real app, this would be more robust
  const match = BIBLE_BOOKS.find(b => 
    b.name.toLowerCase() === normalizedInput || 
    normalizedInput.includes(b.name.toLowerCase())
  );

  return match ? match.name : input; // Fallback to input if not found
};

export const processFile = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
  const extension = file.name.split('.').pop()?.toLowerCase();

  if (extension === 'json') {
    return processJSON(file);
  } else if (extension === 'sqlite' || extension === 'sqlite3') {
    return processSQLite(file);
  } else if (extension === 'zip') {
    return processZip(file);
  } else {
    throw new Error('Formato não suportado. Use .json, .sqlite3 ou .zip');
  }
};

const processJSON = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
  const text = await file.text();
  const data = JSON.parse(text);

  // Expecting structure: { metadata: { name, code }, verses: [{ book, chapter, verse, text }] }
  // OR array of verses
  let rawVerses = [];
  let meta = { code: 'IMP', name: file.name.replace('.json', ''), language: 'pt', importedAt: Date.now() };

  if (Array.isArray(data)) {
    rawVerses = data;
  } else if (data.verses) {
    rawVerses = data.verses;
    if (data.metadata) meta = { ...meta, ...data.metadata };
  } else {
    throw new Error('Estrutura JSON inválida.');
  }

  const verses: Verse[] = rawVerses.map((v: any) => ({
    book: normalizeBookName(v.book_name || v.book),
    chapter: parseInt(v.chapter),
    verse: parseInt(v.verse),
    text: v.text,
    version: meta.code
  }));

  return { meta, verses };
};

const processSQLite = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
    // @ts-ignore - sql.js loaded via CDN
    if (!window.initSqlJs) throw new Error("Biblioteca SQL.js não carregada.");

    // @ts-ignore
    const SQL = await window.initSqlJs({ locateFile: file => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/${file}` });

    const buffer = await file.arrayBuffer();
    const db = new SQL.Database(new Uint8Array(buffer));

    // Try to detect schema. Common schema: table 'verses' (book, chapter, verse, text)
    // Or 'bible_verses' etc.
    let stmt;
    try {
        stmt = db.prepare("SELECT * FROM verses");
    } catch (e) {
        try {
           stmt = db.prepare("SELECT * FROM bible_verses");
        } catch (e2) {
           throw new Error("Tabela de versículos não encontrada no SQLite.");
        }
    }

    const verses: Verse[] = [];
    while (stmt.step()) {
        const row = stmt.getAsObject();
        // Adjust these keys based on common sqlite bible formats if needed
        const bookName = row.book_name || row.book || row.b; 
        const chapter = row.chapter || row.c;
        const verse = row.verse || row.v;
        const text = row.text || row.t || row.content;

        if (bookName && chapter && verse && text) {
             // If book is an ID (integer), we might need to map it. 
             // For this demo, assuming string or standard mapping
             let finalBook = bookName;
             if (typeof bookName === 'number') {
                 // Simple mapping assumption: 1 = Genesis, etc.
                 if (bookName <= 66) finalBook = BIBLE_BOOKS[bookName - 1]?.name;
             }

             verses.push({
                 book: normalizeBookName(String(finalBook)),
                 chapter: Number(chapter),
                 verse: Number(verse),
                 text: String(text),
                 version: 'IMP' 
             });
        }
    }
    stmt.free();
    db.close();

    const meta = { 
        code: `IMP-${Date.now().toString().slice(-4)}`, 
        name: file.name.replace('.sqlite3', ''), 
        language: 'pt', 
        importedAt: Date.now() 
    };

    return { meta, verses: verses.map(v => ({...v, version: meta.code})) };
};

const processZip = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
    const zip = await JSZip.loadAsync(file);

    // Look for a .json or .sqlite file inside
    const jsonFile = Object.values(zip.files).find(f => f.name.endsWith('.json'));
    if (jsonFile) {
        const text = await jsonFile.async('string');
        const virtualFile = new File([text], jsonFile.name, { type: 'application/json' });
        return processJSON(virtualFile);
    }

    const sqliteFile = Object.values(zip.files).find(f => f.name.endsWith('.sqlite') || f.name.endsWith('.sqlite3'));
    if (sqliteFile) {
        const blob = await sqliteFile.async('blob');
        const virtualFile = new File([blob], sqliteFile.name, { type: 'application/x-sqlite3' });
        return processSQLite(virtualFile);
    }

    throw new Error("Nenhum arquivo de Bíblia válido encontrado dentro do ZIP.");
};

import React, { useState } from 'react';
