        </button>

        <h2 className="font-serif text-xl font-bold text-gray-900 dark:text-white mb-2">Importar Bíblia</h2>
        <p className="text-sm text-gray-500 mb-6">Suporta .json, .sqlite3 e .zip</p>

        {status === 'idle' || status === 'error' ? (
          <div 
            className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center text-center transition-colors
              ${dragActive ? 'border-petrol-500 bg-petrol-50 dark:bg-navy-700' : 'border-gray-300 dark:border-gray-600'}
              ${file ? 'bg-petrol-50 dark:bg-navy-700 border-petrol-500' : ''}
            `}
            onDragEnter={handleDrag}
            onDragLeave={handleDrag}
            onDragOver={handleDrag}
            onDrop={handleDrop}
          >
            {file ? (
              <div className="flex flex-col items-center gap-2">
                <FileType size={32} className="text-petrol-600" />
                <span className="font-bold text-gray-700 dark:text-gray-200">{file.name}</span>
