                <button onClick={() => setFile(null)} className="text-xs text-red-500 hover:underline mt-2">Remover</button>
              </div>
            ) : (
              <>
                <Upload size={32} className="text-gray-400 mb-3" />
                <p className="text-sm font-medium text-gray-600 dark:text-gray-300">Arraste um arquivo ou clique para selecionar</p>
                <input 
                  type="file" 
                  className="hidden" 
                  id="file-upload" 
                  accept=".json,.sqlite,.sqlite3,.zip"
