                />
                <label htmlFor="file-upload" className="mt-4 px-4 py-2 bg-white dark:bg-navy-800 border border-gray-300 dark:border-gray-600 rounded-lg text-sm font-bold shadow-sm cursor-pointer hover:bg-gray-50 dark:hover:bg-navy-700 text-gray-700 dark:text-gray-200">
