            ) : (
              <>
                <Loader2 size={40} className="text-petrol-600 animate-spin mb-4" />
                <h3 className="text-lg font-bold text-petrol-700 dark:text-petrol-300">
                  {status === 'processing' ? 'Processando Arquivo...' : 'Salvando no Banco de Dados...'}
                </h3>
                <p className="text-xs text-gray-400 mt-2">Isso pode levar alguns instantes.</p>
              </>
            )}
          </div>
        )}

        {status === 'error' && (
          <div className="mt-4 p-3 bg-red-50 dark:bg-red-900/20 rounded-lg flex items-start gap-2 text-red-600 dark:text-red-400 text-sm">
            <AlertCircle size={16} className="mt-0.5 shrink-0" />
            <p>{errorMessage}</p>
          </div>
        )}

        {(status === 'idle' || status === 'error') && (
          <button 
            onClick={startImport}
            disabled={!file}
            className="w-full mt-6 bg-petrol-600 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-petrol-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            Iniciar Importação
          </button>
        )}
      </div>
    </div>
  );
};

