import React, { useState, useEffect } from 'react';
import { BookMarked, History, Highlighter, Plus, Calendar, Target, Trash2, X, ChevronRight, UploadCloud } from 'lucide-react';
import { BibleReadingPlan } from '../types';
import ImportBibleModal from './ImportBibleModal';

const Library: React.FC = () => {
  const [plans, setPlans] = useState<BibleReadingPlan[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);

  // Form State
  const [newPlanName, setNewPlanName] = useState('');
  const [targetDate, setTargetDate] = useState('');
  const [scope, setScope] = useState<'full' | 'nt' | 'ot'>('full');

  // Constants
  const CHAPTERS_FULL = 1189;
  const CHAPTERS_OT = 929;
  const CHAPTERS_NT = 260;

  const categories = [
    { title: 'Anotações', icon: BookMarked, count: 12 },
    { title: 'Destaques', icon: Highlighter, count: 45 },
    { title: 'Histórico', icon: History, count: null },
  ];

  const getChaptersCount = () => {
    if (scope === 'nt') return CHAPTERS_NT;
    if (scope === 'ot') return CHAPTERS_OT;
    return CHAPTERS_FULL;
  };

  const calculateDailyGoal = (end: string, totalChapters: number) => {
    if (!end) return 0;
    const start = new Date();
    const endDate = new Date(end);
    const diffTime = Math.abs(endDate.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 

    if (diffDays <= 0) return totalChapters; // Late or today
    return Math.ceil(totalChapters / diffDays);
  };

  const handleCreatePlan = () => {
    if (!newPlanName || !targetDate) return;

    const total = getChaptersCount();
    const daily = calculateDailyGoal(targetDate, total);

    const newPlan: BibleReadingPlan = {
      id: Date.now().toString(),
      title: newPlanName,
      startDate: new Date().toISOString(),
      endDate: targetDate,
      totalChapters: total,
      chaptersRead: 0,
      dailyGoal: daily
    };

    setPlans([...plans, newPlan]);
    setShowModal(false);
    // Reset form
    setNewPlanName('');
    setTargetDate('');
    setScope('full');
  };

  const handleDeletePlan = (id: string) => {
    setPlans(plans.filter(p => p.id !== id));
  };

  // Mock initial data if empty
  useEffect(() => {
    if (plans.length === 0) {
      // Optional: Load from local storage or set empty
    }
  }, []);

  const projectedDailyGoal = calculateDailyGoal(targetDate, getChaptersCount());

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 p-6 pb-24 overflow-y-auto relative">
      <div className="flex justify-between items-center mb-6">
