          title="Importar Bíblia"
        >
          <UploadCloud size={24} />
        </button>
      </div>

      {/* Top Categories */}
      <div className="grid grid-cols-2 gap-4 mb-8">
        {categories.map((cat, idx) => (
          <div key={idx} className="bg-white dark:bg-navy-800 p-4 rounded-xl border border-gray-100 dark:border-gray-700 flex flex-col items-center justify-center gap-2 aspect-[4/3] hover:bg-gray-50 dark:hover:bg-navy-700 transition cursor-pointer shadow-sm">
            <cat.icon size={24} className="text-petrol-600 dark:text-petrol-400" />
            <span className="font-medium text-gray-900 dark:text-gray-100 text-sm">{cat.title}</span>
            {cat.count !== null && (
              <span className="text-[10px] text-gray-500 bg-gray-100 dark:bg-navy-900 px-2 py-0.5 rounded-full">{cat.count}</span>
            )}
          </div>
        ))}
      </div>

      {/* Reading Plans Section */}
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-sm font-bold uppercase tracking-wider text-gray-500 dark:text-gray-400">
          Meus Planos de Leitura
        </h2>
        <button 
          onClick={() => setShowModal(true)}
          className="flex items-center gap-1 text-xs font-bold text-petrol-700 dark:text-petrol-300 hover:underline"
        >
          <Plus size={14} /> Novo Plano
        </button>
      </div>

      {plans.length === 0 ? (
        <div 
          onClick={() => setShowModal(true)}
          className="bg-white dark:bg-navy-800 rounded-xl p-8 border-2 border-dashed border-gray-200 dark:border-gray-700 flex flex-col items-center justify-center text-center cursor-pointer hover:border-petrol-300 transition-colors group"
