import JSZip from 'jszip';
import { Verse } from '../types';
import { BIBLE_BOOKS } from '../constants';

// Helper to normalize book names
const normalizeBookName = (input: string): string => {
  const normalizedInput = input.trim().toLowerCase();

  // Simple mapping - In a real app, this would be more robust
  const match = BIBLE_BOOKS.find(b => 
    b.name.toLowerCase() === normalizedInput || 
    normalizedInput.includes(b.name.toLowerCase())
  );

  return match ? match.name : input; // Fallback to input if not found
};

export const processFile = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
  const extension = file.name.split('.').pop()?.toLowerCase();

  if (extension === 'json') {
    return processJSON(file);
  } else if (extension === 'sqlite' || extension === 'sqlite3') {
    return processSQLite(file);
  } else if (extension === 'zip') {
    return processZip(file);
  } else {
    throw new Error('Formato não suportado. Use .json, .sqlite3 ou .zip');
  }
};

const processJSON = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
  const text = await file.text();
  const data = JSON.parse(text);

  // Expecting structure: { metadata: { name, code }, verses: [{ book, chapter, verse, text }] }
  // OR array of verses
  let rawVerses = [];
  let meta = { code: 'IMP', name: file.name.replace('.json', ''), language: 'pt', importedAt: Date.now() };

  if (Array.isArray(data)) {
    rawVerses = data;
  } else if (data.verses) {
    rawVerses = data.verses;
    if (data.metadata) meta = { ...meta, ...data.metadata };
  } else {
    throw new Error('Estrutura JSON inválida.');
  }

  const verses: Verse[] = rawVerses.map((v: any) => ({
    book: normalizeBookName(v.book_name || v.book),
    chapter: parseInt(v.chapter),
    verse: parseInt(v.verse),
    text: v.text,
    version: meta.code
  }));

  return { meta, verses };
};

const processSQLite = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
    // @ts-ignore - sql.js loaded via CDN
    if (!window.initSqlJs) throw new Error("Biblioteca SQL.js não carregada.");

    // @ts-ignore
    const SQL = await window.initSqlJs({ locateFile: file => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/${file}` });

    const buffer = await file.arrayBuffer();
    const db = new SQL.Database(new Uint8Array(buffer));

    // Try to detect schema. Common schema: table 'verses' (book, chapter, verse, text)
    // Or 'bible_verses' etc.
    let stmt;
    try {
        stmt = db.prepare("SELECT * FROM verses");
    } catch (e) {
        try {
           stmt = db.prepare("SELECT * FROM bible_verses");
        } catch (e2) {
           throw new Error("Tabela de versículos não encontrada no SQLite.");
        }
    }

    const verses: Verse[] = [];
    while (stmt.step()) {
        const row = stmt.getAsObject();
        // Adjust these keys based on common sqlite bible formats if needed
        const bookName = row.book_name || row.book || row.b; 
        const chapter = row.chapter || row.c;
        const verse = row.verse || row.v;
        const text = row.text || row.t || row.content;

        if (bookName && chapter && verse && text) {
             // If book is an ID (integer), we might need to map it. 
             // For this demo, assuming string or standard mapping
             let finalBook = bookName;
             if (typeof bookName === 'number') {
                 // Simple mapping assumption: 1 = Genesis, etc.
                 if (bookName <= 66) finalBook = BIBLE_BOOKS[bookName - 1]?.name;
             }

             verses.push({
                 book: normalizeBookName(String(finalBook)),
                 chapter: Number(chapter),
                 verse: Number(verse),
                 text: String(text),
                 version: 'IMP' 
             });
        }
    }
    stmt.free();
    db.close();

    const meta = { 
        code: `IMP-${Date.now().toString().slice(-4)}`, 
        name: file.name.replace('.sqlite3', ''), 
        language: 'pt', 
        importedAt: Date.now() 
    };

    return { meta, verses: verses.map(v => ({...v, version: meta.code})) };
};

const processZip = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
    const zip = await JSZip.loadAsync(file);
    const files = Object.values(zip.files) as any[];

    // Look for a .json or .sqlite file inside
    const jsonFile = files.find(f => f.name.endsWith('.json'));
    if (jsonFile) {
        const text = await jsonFile.async('string');
        const virtualFile = new File([text], jsonFile.name, { type: 'application/json' });
        return processJSON(virtualFile);
    }

    const sqliteFile = files.find(f => f.name.endsWith('.sqlite') || f.name.endsWith('.sqlite3'));
    if (sqliteFile) {
        const blob = await sqliteFile.async('blob');
        const virtualFile = new File([blob], sqliteFile.name, { type: 'application/x-sqlite3' });
        return processSQLite(virtualFile);
    }

    throw new Error("Nenhum arquivo de Bíblia válido encontrado dentro do ZIP.");
};

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, MessageSquarePlus, Settings, Book, Heart, Check, X, Loader2 } from 'lucide-react';
import { MOCK_VERSES, BIBLE_BOOKS } from '../constants';
import { getTheologicalInsight, getBibleChapter } from '../services/geminiService';
import { getStoredChapter, getStoredVersions, StoredBibleMeta } from '../services/db';
import { BibleVersion, Verse } from '../types';

const BibleReader: React.FC = () => {
  const [chapter, setChapter] = useState(8);
  const [book, setBook] = useState("Romanos");
  const [fontSize, setFontSize] = useState(18);
  const [isParallel, setIsParallel] = useState(false);
  const [selectedVerse, setSelectedVerse] = useState<string | null>(null); // Stores verse key "book-chap-verse"
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Versions and Favorites
  const [primaryVersion, setPrimaryVersion] = useState<string>('ARA');
  const [secondaryVersion, setSecondaryVersion] = useState<string>('NA28');
  const [favorites, setFavorites] = useState<string[]>([]); // Array of "book-chap-verse"
  const [showVersionSelector, setShowVersionSelector] = useState<'primary' | 'secondary' | null>(null);

  // Custom/Imported Versions List
  const [customVersions, setCustomVersions] = useState<StoredBibleMeta[]>([]);

  // Dynamic Content State
  const [primaryContent, setPrimaryContent] = useState<Verse[]>([]);
  const [secondaryContent, setSecondaryContent] = useState<Verse[]>([]);
  const [isLoadingText, setIsLoadingText] = useState(false);

  // Navigation Modal State
  const [showNav, setShowNav] = useState(false);
  const [navTab, setNavTab] = useState<'AT' | 'NT'>('NT');
  const [selectedBookForNav, setSelectedBookForNav] = useState<string | null>(null);

  // Load custom versions on mount
  useEffect(() => {
    getStoredVersions().then(setCustomVersions).catch(console.error);
  }, []);

  // Load Content Effect
  useEffect(() => {
    const loadContent = async () => {
      setIsLoadingText(true);

      const fetchVersionText = async (vCode: string): Promise<Verse[]> => {
        // 1. Check Mock Data (Standard versions)
        const local = MOCK_VERSES.filter(v => v.book === book && v.chapter === chapter && v.version === vCode);
        if (local.length > 0) return local;

        // 2. Check IndexedDB (Imported versions)
        try {
          const stored = await getStoredChapter(vCode, book, chapter);
          if (stored && stored.length > 0) return stored;
        } catch (e) {
          console.error("Erro ao ler do banco local:", e);
        }

        // 3. Fallback to Gemini (Only for standard predefined versions)
        const standardVersions = ['ARA', 'NVT', 'KJV', 'NA28', 'BHS'];
        if (standardVersions.includes(vCode)) {
          return await getBibleChapter(book, chapter, vCode as BibleVersion);
        }

        return [];
      };

      // Load Primary
      const pText = await fetchVersionText(primaryVersion);
      setPrimaryContent(pText);

      // Load Secondary
      if (isParallel) {
        const sText = await fetchVersionText(secondaryVersion);
        setSecondaryContent(sText);
      }

      setIsLoadingText(false);
    };

    loadContent();
  }, [book, chapter, primaryVersion, secondaryVersion, isParallel]);


  // Helper to generate a unique key for a verse (independent of version)
  const getVerseKey = (v: { book: string, chapter: number, verse: number }) => `${v.book}-${v.chapter}-${v.verse}`;

  const handleVerseClick = (vKey: string) => {
    setSelectedVerse(selectedVerse === vKey ? null : vKey);
    setAiInsight(null);
  };

  const toggleFavorite = (vKey: string) => {
    setFavorites(prev => 
      prev.includes(vKey) ? prev.filter(k => k !== vKey) : [...prev, vKey]
    );
  };

  const requestInsight = async (text: string) => {
    setLoadingAi(true);
    const insight = await getTheologicalInsight(
      `Explique teologicamente o versículo: "${text}" à luz da teologia reformada. Se houver termos no original (Grego/Hebraico) relevantes, mencione. Seja breve.`,
      'biblical'
    );
    setAiInsight(insight);
    setLoadingAi(false);
  };

  const handleBookSelect = (bookName: string) => {
    setSelectedBookForNav(bookName);
  };

  const handleChapterSelect = (chap: number) => {
    if (selectedBookForNav) {
      setBook(selectedBookForNav);
      setChapter(chap);
      setShowNav(false);
      setSelectedBookForNav(null); // Reset for next time
    }
  };

  // --- Typography Helpers ---
  const isRTL = (ver: string) => ver === 'BHS';

  const getFontSettings = (ver: string) => {
    if (ver === 'BHS') {
      return {
        className: 'font-serif leading-loose text-right font-medium tracking-wide',
        scale: 1.25 // Hebrew needs to be larger to be readable
      };
    }
    if (ver === 'NA28') {
      return {
        className: 'font-serif leading-relaxed tracking-wide',
        scale: 1.0
      };
    }
    return {
      className: 'reading-text leading-loose text-left',
      scale: 1.0
    };
  };

  const standardVersionsList: { code: string, label: string }[] = [
    { code: 'ARA', label: 'Almeida Revista e Atualizada' },
    { code: 'NVT', label: 'Nova Versão Transformadora' },
    { code: 'KJV', label: 'King James Version' },
    { code: 'NA28', label: 'Nestle-Aland 28 (Grego)' },
    { code: 'BHS', label: 'Biblia Hebraica (Hebraico)' },
  ];

  const allAvailableVersions = [
    ...standardVersionsList,
    ...customVersions.map(cv => ({ code: cv.code, label: cv.name + ' (Importada)' }))
  ];

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 relative">

      {/* Navigation Modal */}
      {showNav && (
        <div className="absolute inset-0 z-50 bg-white dark:bg-navy-900 animate-fade-in flex flex-col">
          {/* Nav Header */}
          <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-800 flex items-center justify-between bg-white dark:bg-navy-900 sticky top-0">
             {selectedBookForNav ? (
               <button onClick={() => setSelectedBookForNav(null)} className="flex items-center gap-1 text-gray-500 hover:text-petrol-600">
                 <ChevronLeft size={20} /> <span className="text-sm font-bold">Voltar</span>
               </button>
             ) : (
               <h2 className="text-lg font-serif font-bold text-petrol-900 dark:text-white">Navegar</h2>
             )}
             <button onClick={() => { setShowNav(false); setSelectedBookForNav(null); }} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-navy-800 text-gray-500">
               <X size={24} />
             </button>
          </div>

          {/* Content */}
          <div className="flex-1 overflow-y-auto">
            {!selectedBookForNav ? (
              // Book Selection List
              <div className="p-4">
                {/* Tabs */}
                <div className="flex bg-gray-100 dark:bg-navy-800 p-1 rounded-xl mb-6 sticky top-0 z-10">
                  {(['AT', 'NT'] as const).map(tab => (
                    <button
                      key={tab}
                      onClick={() => setNavTab(tab)}
                      className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${
                        navTab === tab 
                          ? 'bg-white dark:bg-navy-700 text-petrol-700 dark:text-white shadow-sm' 
                          : 'text-gray-500 dark:text-gray-400'
                      }`}
                    >
                      {tab === 'AT' ? 'Antigo Testamento' : 'Novo Testamento'}
                    </button>
                  ))}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  {BIBLE_BOOKS.filter(b => b.test === navTab).map(b => (
                    <button 
                      key={b.name}
                      onClick={() => handleBookSelect(b.name)}
                      className="text-left px-4 py-3 rounded-lg hover:bg-petrol-50 dark:hover:bg-navy-800 border border-transparent hover:border-petrol-100 dark:hover:border-navy-700 transition-colors"
                    >
                      <span className="font-serif font-medium text-gray-800 dark:text-gray-200">{b.name}</span>
                    </button>
                  ))}
                </div>
              </div>
            ) : (
              // Chapter Selection Grid
              <div className="p-6">
                <h3 className="text-center font-serif text-2xl font-bold text-gray-900 dark:text-white mb-8">
                  {selectedBookForNav}
                </h3>
                <div className="grid grid-cols-5 gap-4">
                   {Array.from({ length: BIBLE_BOOKS.find(b => b.name === selectedBookForNav)?.chapters || 0 }, (_, i) => i + 1).map(chapNum => (
                     <button
                       key={chapNum}
                       onClick={() => handleChapterSelect(chapNum)}
                       className={`aspect-square rounded-full flex items-center justify-center font-medium text-lg transition-all
                         ${(book === selectedBookForNav && chapter === chapNum)
                           ? 'bg-petrol-600 text-white shadow-md' 
                           : 'bg-gray-100 dark:bg-navy-800 text-gray-700 dark:text-gray-300 hover:bg-petrol-100 dark:hover:bg-navy-700'
                         }
                       `}
                     >
                       {chapNum}
                     </button>
                   ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Version Selector Modal/Dropdown Overlay */}
      {showVersionSelector && (
        <div className="absolute inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-start justify-center pt-20 animate-fade-in" onClick={() => setShowVersionSelector(null)}>
          <div className="bg-white dark:bg-navy-800 rounded-xl shadow-2xl w-72 max-h-[80vh] overflow-hidden border border-gray-200 dark:border-gray-700 flex flex-col" onClick={e => e.stopPropagation()}>
            <div className="p-3 bg-petrol-50 dark:bg-navy-900 border-b border-gray-100 dark:border-gray-700 flex-shrink-0">
              <h3 className="text-xs font-bold uppercase tracking-wider text-gray-500">
                Selecione a Versão {showVersionSelector === 'secondary' ? 'Secundária' : 'Principal'}
              </h3>
            </div>
            <div className="overflow-y-auto flex-1">
              {allAvailableVersions.map(v => (
                <button
                  key={v.code}
                  onClick={() => {
                    if (showVersionSelector === 'primary') setPrimaryVersion(v.code);
                    else setSecondaryVersion(v.code);
                    setShowVersionSelector(null);
                  }}
                  className="w-full text-left px-4 py-3 text-sm hover:bg-gray-50 dark:hover:bg-navy-700 flex items-center justify-between text-gray-800 dark:text-gray-200 border-b border-gray-50 dark:border-gray-800/50"
                >
                  <div className="flex flex-col">
                    <span className="font-bold">{v.code}</span>
                    <span className="text-xs text-gray-500">{v.label}</span>
                  </div>
                  {(showVersionSelector === 'primary' ? primaryVersion : secondaryVersion) === v.code && <Check size={16} className="text-petrol-600" />}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Top Bar Controls */}
      <div className="sticky top-0 bg-white/95 dark:bg-navy-900/95 backdrop-blur-sm border-b border-gray-200 dark:border-gray-800 px-4 py-3 flex items-center justify-between z-10">
         <div className="flex items-center gap-2">
            <button 
              onClick={() => setChapter(c => Math.max(1, c - 1))}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"
            >
               <ChevronLeft size={20} className="text-gray-600 dark:text-gray-300" />
            </button>
            <div 
              onClick={() => { setShowNav(true); setSelectedBookForNav(null); }}
              className="flex flex-col items-center cursor-pointer group hover:bg-gray-50 dark:hover:bg-white/5 px-4 py-1 rounded-lg transition-colors"
            >
              <span className="font-serif font-bold text-gray-900 dark:text-white flex items-center gap-1">
                {book} {chapter}
              </span>
              <div className="flex items-center gap-1 text-[10px] text-gray-500 uppercase tracking-wide" onClick={e => e.stopPropagation()}>
                <span 
                  onClick={() => setShowVersionSelector('primary')}
                  className="hover:text-petrol-600 hover:underline cursor-pointer"
                >
                  {primaryVersion}
                </span>
                {isParallel && (
                  <>
                    <span>&</span>
                    <span 
                      onClick={() => setShowVersionSelector('secondary')}
                      className="hover:text-petrol-600 hover:underline cursor-pointer"
                    >
                      {secondaryVersion}
                    </span>
                  </>
                )}
              </div>
            </div>
            <button 
              onClick={() => setChapter(c => c + 1)}
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full"
            >
               <ChevronRight size={20} className="text-gray-600 dark:text-gray-300" />
            </button>
         </div>
         <div className="flex items-center gap-2">
            <button 
              onClick={() => setIsParallel(!isParallel)} 
              className={`p-2 rounded-full transition-colors ${isParallel ? 'bg-petrol-100 text-petrol-700 dark:bg-petrol-900 dark:text-petrol-100' : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800'}`}
              title="Modo Paralelo"
            >
              <Book size={18} />
            </button>
            <button className="text-gray-500 dark:text-gray-400 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full">
              <Settings size={20} />
            </button>
         </div>
      </div>

      {/* Reader Area */}
      <div className="flex-1 overflow-y-auto p-4 pb-32">
        <div className={`mx-auto ${isParallel ? 'w-full max-w-6xl' : 'max-w-2xl'}`}>
          <div className="text-center mb-8">
             <h1 className="font-serif text-3xl font-bold text-gray-900 dark:text-white mb-2">{book}</h1>
             <span className="text-4xl font-serif text-gray-200 dark:text-gray-700">{chapter}</span>
          </div>

          {isLoadingText ? (
            <div className="flex flex-col items-center justify-center py-20 space-y-4">
               <Loader2 size={40} className="text-petrol-600 animate-spin" />
               <p className="text-sm text-gray-500 animate-pulse">Carregando {primaryVersion}...</p>
            </div>
          ) : (
          <div className="space-y-4">
            {primaryContent.length === 0 ? (
              <div className="text-center py-10 bg-gray-50 dark:bg-navy-800 rounded-2xl border border-dashed border-gray-300 dark:border-gray-700 mx-auto max-w-md">
                <Book size={48} className="mx-auto text-gray-300 dark:text-gray-600 mb-4" />
                <h3 className="text-lg font-bold text-gray-700 dark:text-gray-300 mb-2">Texto Indisponível</h3>
                <p className="text-sm text-gray-500 dark:text-gray-400 px-6">
                  Não foi possível carregar o texto deste capítulo nesta versão ({primaryVersion}).
                </p>
              </div>
            ) : (
              primaryContent.map((verse, idx) => {
                const vKey = getVerseKey(verse);
                const isSelected = selectedVerse === vKey;
                const isFav = favorites.includes(vKey);

                // Try to find matching verse in secondary content
                const secondaryVerseText = secondaryContent.find(v => v.verse === verse.verse)?.text;

                // Typography Settings
                const primaryStyle = getFontSettings(primaryVersion);
                const secondaryStyle = getFontSettings(secondaryVersion);

                return (
                  <div 
                    key={vKey} 
                    className={`relative rounded-xl transition-all duration-300 
                      ${isSelected 
                        ? 'bg-white dark:bg-navy-800 shadow-lg ring-1 ring-petrol-500/20 -mx-3 px-3 py-4 my-4' 
                        : 'hover:bg-white/50 dark:hover:bg-white/5 border-b border-transparent'}`}
                  >
                    <div className={`grid ${isParallel ? 'grid-cols-1 md:grid-cols-2 gap-4 md:gap-8 divide-y md:divide-y-0 md:divide-x divide-gray-100 dark:divide-gray-800' : 'grid-cols-1'}`}>

                      {/* Primary Version Column */}
                      <div className={`relative ${isParallel ? 'pb-2 md:pb-0' : ''}`}>
                         <span className={`text-[10px] font-bold absolute -left-0 top-1.5 w-6 text-gray-400 select-none ${isFav ? 'text-gold-500' : ''}`}>
                           {verse.verse}
                         </span>
                         <div className="pl-6">
                            <p 
                              onClick={() => handleVerseClick(vKey)}
                              dir={isRTL(primaryVersion) ? "rtl" : "ltr"}
                              className={`${primaryStyle.className} text-gray-800 dark:text-gray-200 cursor-pointer transition-colors hover:text-petrol-700 dark:hover:text-petrol-300`}
                              style={{ fontSize: `${fontSize * primaryStyle.scale}px` }}
                            >
                              {verse.text}
                            </p>
                         </div>
                      </div>

                      {/* Secondary Version Column (Parallel Mode) */}
                      {isParallel && (
                         <div className={`relative ${isParallel ? 'pt-2 md:pt-0 md:pl-8' : ''}`}>
                            {secondaryVerseText ? (
                              <p 
                                onClick={() => handleVerseClick(vKey)}
                                dir={isRTL(secondaryVersion) ? "rtl" : "ltr"}
                                className={`${secondaryStyle.className} text-gray-600 dark:text-gray-400 cursor-pointer transition-colors hover:text-petrol-700 dark:hover:text-petrol-300`}
                                style={{ fontSize: `${fontSize * secondaryStyle.scale}px` }}
                              >
                                {secondaryVerseText}
                              </p>
                            ) : (
                              <span className="text-xs text-gray-300 italic flex items-center h-full pt-1">
                                {secondaryContent.length > 0 ? "..." : "Carregando..."}
                              </span>
                            )}
                         </div>
                      )}
                    </div>

                    {/* Action Menu (Visible on Select) */}
                    {isSelected && (
                      <div className="mt-4 flex gap-3 animate-fade-in pl-6 border-t border-gray-100 dark:border-gray-700 pt-3">
                        <button 
                          onClick={() => toggleFavorite(vKey)}
                          className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-full border transition-colors
                            ${isFav 
                              ? 'bg-gold-50 border-gold-200 text-gold-600 dark:bg-gold-900/20 dark:border-gold-700' 
                              : 'bg-white border-gray-200 text-gray-600 hover:border-petrol-300 dark:bg-navy-700 dark:border-gray-600 dark:text-gray-300'}`}
                        >
                          <Heart size={14} fill={isFav ? "currentColor" : "none"} />
                          {isFav ? 'Salvo' : 'Salvar'}
                        </button>

                        <button 
                          onClick={() => requestInsight(verse.text)}
                          className="flex items-center gap-2 px-3 py-1.5 bg-petrol-600 text-white text-xs font-bold rounded-full shadow hover:bg-petrol-700 transition"
                        >
                          <MessageSquarePlus size={14} />
                          {loadingAi ? 'Analisando...' : 'Insight Teológico'}
                        </button>
                      </div>
                    )}

                    {/* AI Insight Result */}
                    {isSelected && aiInsight && (
                       <div className="mt-4 mx-6 p-4 bg-petrol-50 dark:bg-navy-900/50 border border-petrol-100 dark:border-petrol-900 rounded-lg text-sm text-gray-800 dark:text-gray-200 leading-relaxed animate-fade-in">
                          <h4 className="font-bold text-petrol-700 dark:text-petrol-300 mb-2 flex items-center gap-2 text-xs uppercase tracking-wider">
                             <MessageSquarePlus size={14} /> Comentário Reformado
                          </h4>
                          <div dangerouslySetInnerHTML={{ __html: aiInsight.replace(/\n/g, '<br/>') }} />
                       </div>
                    )}
                  </div>
                );
              })
            )}
          </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default BibleReader;
